function doGet(e) {
  if (!e || !e.parameter) {
    return ContentService.createTextOutput(JSON.stringify({
      status: 'sukses',
      message: 'Server backend berjalan.'
    })).setMimeType(ContentService.MimeType.JSON);
  }

  try {
    const action = e.parameter.action;

    // FITUR LUPA PASSWORD
    if (action === 'forgot_password') {
      const email = (e.parameter.email || "").trim().toLowerCase();
      if (!email) return response({ status: 'error', message: 'Email tidak boleh kosong' });

      const users = getSheetData('Karyawan');
      const user = users.find(u => (u.email || "").toString().toLowerCase().trim() === email);

      if (user) {
        try {
          MailApp.sendEmail({
            to: user.email,
            subject: "Pemulihan Password - Flow Salon Portal",
            body: `Halo ${user.nama},\n\nPassword Anda adalah: ${user.password}\n\nSalam,\nFlow Salon IT`
          });
          return response({ status: 'sukses', message: 'Password telah dikirim ke emailmu.' });
        } catch (mailErr) {
          return response({ status: 'error', message: 'Gagal kirim email: ' + mailErr.toString() });
        }
      } else {
        return response({ status: 'error', message: 'Masukkan email yang terdaftar.' });
      }
    }

    if (action === 'get_initial_data') {
      const email = (e.parameter.email || "").toLowerCase().trim();

      // Ambil SEMUA materi
      const materiList = getSheetData('Materi'); 

      // LOGIKA BARU: Ambil Join Date dari Sheet Karyawan
      let joinDate = null;
      if (email) {
        const employees = getSheetData('Karyawan');
        const emp = employees.find(u => (u.email || "").toString().toLowerCase().trim() === email);
        if (emp) {
          // Mengambil kolom timestamp (biasanya kolom A / 'timestamp' atau 'waktu')
          // Menambahkan 'temestamp' untuk handle typo user di nama kolom Sheet
          joinDate = emp.timestamp || emp.temestamp || emp.waktu || null;
        }
      }

      // Cari log absensi terakhir user ini untuk menentukan progress materi
      let lastLog = null;
      if (email) {
        const allSheets = SS.getSheets();
        const absenSheets = allSheets.filter(s => s.getName().startsWith("Absensi_"));
        absenSheets.sort((a, b) => b.getName().localeCompare(a.getName()));

        for (const sheet of absenSheets) {
          const data = getSheetData(sheet.getName());
          const userLogs = data.filter(row => (row.email || "").toString().toLowerCase() === email);
          if (userLogs.length > 0) {
            const lastEntry = userLogs[userLogs.length - 1];
            lastLog = {
              waktu: lastEntry.waktu,
              materi: lastEntry.progress_materi || "" 
            };
            break; 
          }
        }
      }

      return response({
        materiList: materiList, 
        lastLog: lastLog,
        joinDate: joinDate, // Return join date ke frontend
        sop: getSheetData('SOP'),
        pesanManager: getSheetData('PesanManager')?.reverse()[0] || { pesan: "Selamat Bekerja!", nama: "Manager", jabatan: "Salon Manager" },
        tugasDef: getSheetData('TugasDef'), 
        lokasi: getSheetData('Lokasi'),
        tips: getSheetData('Tips')
      });
    }

    if (action === 'get_history') {
      const email = (e.parameter.email || "").toLowerCase();
      const allSheets = SS.getSheets();
      let history = [];

      allSheets.forEach(s => {
        if (s.getName().startsWith("Absensi_")) {
          const data = getSheetData(s.getName());
          const filtered = data.filter(row => (row.email || "").toString().toLowerCase() === email);
          history = history.concat(filtered);
        }
      });

      history.sort((a, b) => new Date(b.waktu) - new Date(a.waktu));
      return response(history);
    }

    if (action === 'get_checklist_history') {
      const email = (e.parameter.email || "").toLowerCase();
      const nama = (e.parameter.nama || "").toLowerCase();
      const allSheets = SS.getSheets();
      let history = [];

      allSheets.forEach(s => {
        if (s.getName().startsWith("Checklist_")) {
          const data = getSheetData(s.getName());
          const filtered = data.filter(row => 
            (row.email || "").toString().toLowerCase() === email || 
            (row.nama || "").toString().toLowerCase() === nama
          );
          history = history.concat(filtered);
        }
      });
      return response(history);
    }

    if (action === 'login') {
      const email = (e.parameter.email || "").toLowerCase().trim();
      const pass = (e.parameter.pass || "").toString();
      const users = getSheetData('Karyawan');
      const user = users.find(u => (u.email || "").toString().toLowerCase().trim() === email && u.password.toString() === pass);

      if (user) {
        return response({ 
          status: 'sukses', 
          nama: user.nama, 
          email: user.email, 
          jabatan: user.jabatan 
        });
      } else {
        return response({ status: 'error', message: 'Email atau Password salah' });
      }
    }

    return response({ status: 'error', message: 'Action tidak valid' });

  } catch (err) {
    return response({ status: 'error', message: 'Server Error: ' + err.toString() });
  }
}

function doPost(e) {
  try {
    const p = JSON.parse(e.postData.contents);
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth() + 1;
    const timeStr = Utilities.formatDate(now, "GMT+7", "yyyyMMdd_HHmm");

    let quarter = "Q1";
    if (month >= 4 && month <= 6) quarter = "Q2";
    else if (month >= 7 && month <= 9) quarter = "Q3";
    else if (month >= 10 && month <= 12) quarter = "Q4";

    if (p.type === 'signup') {
      const sheet = SS.getSheetByName('Karyawan');
      let ktpUrl = "No Photo";
      if (p.fotoKTP && p.fotoKTP.includes("base64")) {
        ktpUrl = saveFileToDrive(p.fotoKTP, FOLDER_ID_KTP, `KTP_${p.nama}_${timeStr}`);
      }
      sheet.appendRow([now, p.nama, p.email, p.password, p.jabatan, p.ttl, p.wa, ktpUrl, p.k_nama, p.k_hub, p.k_wa]);
      return response({ status: 'sukses' });
    }

    if (p.type === 'absen') {
      const sheetName = `Absensi_${year}_${quarter}`;
      let sheet = SS.getSheetByName(sheetName) || SS.insertSheet(sheetName);

      // Update Header jika sheet baru atau header lama
      if (sheet.getLastRow() === 0) {
        sheet.appendRow(['Waktu', 'Nama', 'Email', 'Jenis', 'Shift', 'Cabang', 'GPS', 'Status_Lokasi', 'Link_Foto_Drive', 'Progress_Materi']);
        sheet.getRange(1, 1, 1, 10).setFontWeight("bold").setBackground("#d1fadf");
      } else {
        const header = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
        if (header.length < 10 || header[9] !== 'Progress_Materi') {
          sheet.getRange(1, 10).setValue('Progress_Materi').setFontWeight("bold").setBackground("#d1fadf");
        }
      }

      let fotoUrl = "No Photo";
      if (p.foto && p.foto.includes("base64")) {
        fotoUrl = saveFileToDrive(p.foto, FOLDER_ID_ABSEN, `ABSEN_${p.jenis}_${p.nama}_${timeStr}`);
      }

      const materiRead = p.materi || "-";

      sheet.appendRow([now, p.nama, p.email, p.jenis, p.shift, p.cabang, `${p.lat},${p.lng}`, p.statusLokasi, fotoUrl, materiRead]);
      return response({ status: 'sukses' });
    }

    if (p.type === 'tugas') {
      const sheetName = `Checklist_${year}_${quarter}`;
      let sheet = SS.getSheetByName(sheetName) || SS.insertSheet(sheetName);

      if (sheet.getLastRow() === 0) {
        sheet.appendRow(['Waktu', 'Nama', 'Jabatan', 'Jenis_Checklist', 'Ringkasan', 'Skor_%', 'Data_Laporan_JSON']);
        sheet.getRange(1, 1, 1, 7).setFontWeight("bold").setBackground("#e0f2fe");
      }

      const ringkasan = `${p.totalSelesai} dari ${p.totalTugas} selesai`;
      const skor = p.totalTugas > 0 ? (p.totalSelesai / p.totalTugas) * 100 : 0;

      sheet.appendRow([now, p.nama, p.jabatan, p.jenis, ringkasan, skor.toFixed(0) + "%", JSON.stringify(p.checklist)]);
      return response({ status: 'sukses' });
    }

    return response({ status: 'error', message: 'Invalid Post Type' });
  } catch (err) {
    return response({ status: 'error', message: 'Post Error: ' + err.toString() });
  }
}

function saveFileToDrive(base64Data, folderId, fileName) {
  try {
    const splitData = base64Data.split(',');
    const contentType = splitData[0].match(/:(.*?);/)[1];
    const byteData = Utilities.base64Decode(splitData[1]);
    const blob = Utilities.newBlob(byteData, contentType, fileName);
    const folder = DriveApp.getFolderById(folderId);
    const file = folder.createFile(blob);
    file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
    return file.getUrl();
  } catch (e) { return "Error: " + e.toString(); }
}

function response(obj) {
  return ContentService.createTextOutput(JSON.stringify(obj)).setMimeType(ContentService.MimeType.JSON);
}

function getSheetData(name) {
  const sheet = SS.getSheetByName(name);
  if (!sheet) return [];
  const values = sheet.getDataRange().getValues();
  if (values.length < 2) return [];
  const heads = values.shift();
  const cleanHeads = heads.map(h => h.toString().toLowerCase().trim().replace(/\s+/g, '_'));

  return values.map(row => cleanHeads.reduce((obj, h, i) => {
    let val = row[i];
    if (val instanceof Date) {
      obj[h] = val.toISOString();
    } else if (h === 'waktu' && val) {
      try {
        obj[h] = new Date(val).toISOString();
      } catch(e) {
        obj[h] = val;
      }
    } else {
      obj[h] = val;
    }
    return obj;
  }, {}));
}

import React, { useState, useEffect, useRef } from 'react';
import { api } from '../services/apiService';
import { User } from '../types';
import { CheckCircleIcon } from '../components/Icons';

interface AttendanceProps {
  user: User;
  onAttendanceSuccess: () => void;
  lokasiData: any[];
  currentMateri: any; 
  joinDate?: string | null;
}

interface HistoryItem {
  waktu: string;
  jenis: string;
  cabang: string;
  shift: string;
}

interface GroupedHistory {
  dateKey: string;
  dateDisplay: string;
  shortDate: string;
  monthYear: string;
  cabang: string; 
  shift: string;
  masuk?: string;
  pulang?: string;
  status?: 'TEPAT WAKTU' | 'TELAT';
}

const calculateDistance = (lat1: number, lon1: number, lat2: number, lon2: number): number => {
  const R = 6371e3; // metres
  const φ1 = lat1 * Math.PI / 180;
  const φ2 = lat2 * Math.PI / 180;
  const Δφ = (lat2 - lat1) * Math.PI / 180;
  const Δλ = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(Δφ / 2) * Math.sin(Δφ / 2) + Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
};

const parseLocalDate = (dateStr: any): Date | null => {
  try {
    if (!dateStr) return null;
    if (dateStr instanceof Date) return isNaN(dateStr.getTime()) ? null : dateStr;

    const s = String(dateStr).trim();
    const nativeDate = new Date(s);
    if (!isNaN(nativeDate.getTime())) return nativeDate;

    const datePart = s.split(/[ ,T]+/)[0];
    const bits = datePart.split(/[\/\-\.]/);

    if (bits.length === 3) {
      let d, m, y;
      const b0 = parseInt(bits[0]);
      const b1 = parseInt(bits[1]);
      const b2 = parseInt(bits[2]);

      if (bits[2].length === 4) {
        if (b0 > 12) { d = b0; m = b1; y = b2; } 
        else { m = b0; d = b1; y = b2; }
      } else if (bits[0].length === 4) {
        y = b0; m = b1; d = b2;
      } else return null;

      const finalDate = new Date(y, m - 1, d);
      const timePart = s.split(/[ ,T]+/)[1];
      if (timePart) {
        const tBits = timePart.split(/[:\.]/);
        if (tBits.length >= 2) {
          finalDate.setHours(parseInt(tBits[0]), parseInt(tBits[1]), parseInt(tBits[2] || "0"));
        }
      }
      return isNaN(finalDate.getTime()) ? null : finalDate;
    }
    return null;
  } catch (e) { return null; }
};

export const Attendance: React.FC<AttendanceProps> = ({ user, onAttendanceSuccess, lokasiData, currentMateri, joinDate }) => {
  const [activeView, setActiveView] = useState<'absen' | 'laporan'>('absen');
  const [currentTime, setCurrentTime] = useState(new Date());
  const [jenis, setJenis] = useState('Masuk');
  const [shift, setShift] = useState('');
  const [cabang, setCabang] = useState('');
  const [photo, setPhoto] = useState<string | null>(null);
  const [isCameraOpen, setIsCameraOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [gps, setGps] = useState<{ lat: number, lng: number, accuracy: number } | null>(null);
  const [attendanceHistory, setAttendanceHistory] = useState<HistoryItem[]>([]);

  const [showSuccessView, setShowSuccessView] = useState(false);

  const now = new Date();
  const monthFullNames = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
  const currentMonthYearFilter = `${monthFullNames[now.getMonth()]} ${now.getFullYear()}`;
  const [selectedMonth, setSelectedMonth] = useState<string>(currentMonthYearFilter);
  const [isSyncing, setIsSyncing] = useState(false);

  const [distance, setDistance] = useState<number | null>(null);
  const [allowedRadius, setAllowedRadius] = useState<number>(100);
  const [isInsideRadius, setIsInsideRadius] = useState<boolean | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    const forceView = localStorage.getItem('force_attendance_view');
    if (forceView === 'laporan') {
      setActiveView('laporan');
      localStorage.removeItem('force_attendance_view');
    }
  }, []);

  useEffect(() => {
    const fetchHistory = async () => {
      setIsSyncing(true);
      try {
        const history = await api.getAttendanceHistory(user.email);
        if (history && Array.isArray(history)) {
          const sorted = [...history].sort((a, b) => new Date(a.waktu).getTime() - new Date(b.waktu).getTime());
          setAttendanceHistory(sorted);
        }
      } catch (err) {
        console.error("Gagal ambil history:", err);
      } finally {
        setIsSyncing(false);
      }
    };
    fetchHistory();
  }, [user.email, activeView]);

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    if (navigator.geolocation) {
      const watcher = navigator.geolocation.watchPosition(
        (pos) => setGps({ lat: pos.coords.latitude, lng: pos.coords.longitude, accuracy: pos.coords.accuracy }),
        (err) => console.error(err), 
        { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
      );
      return () => {
        navigator.geolocation.clearWatch(watcher);
        clearInterval(timer);
      };
    }
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    if (gps && cabang && lokasiData.length > 0) {
      const targetCabang = lokasiData.find(l => {
        const nameInSheet = String(l?.namacabang || l?.nama || l?.Nama || "").toUpperCase();
        return nameInSheet === cabang.toUpperCase();
      });

      if (targetCabang) {
        const latTarget = parseFloat(targetCabang.latitude || targetCabang.lat);
        const lngTarget = parseFloat(targetCabang.longitude || targetCabang.lng);
        const radiusTarget = parseFloat(targetCabang.radiusmeter || targetCabang.radius || 100);
        if (!isNaN(latTarget) && !isNaN(lngTarget)) {
          const dist = calculateDistance(gps.lat, gps.lng, latTarget, lngTarget);
          setDistance(dist);
          setAllowedRadius(radiusTarget);
          setIsInsideRadius(dist <= radiusTarget);
        } else {
          setDistance(null);
          setIsInsideRadius(true);
        }
      }
    }
  }, [gps, cabang, lokasiData]);

  const lastTodayRecord = [...attendanceHistory].reverse().find(h => {
    const date = parseLocalDate(h.waktu);
    return date && date.toDateString() === new Date().toDateString();
  });

  const isCurrentlyCheckedIn = lastTodayRecord?.jenis === 'Masuk';

  useEffect(() => {
    if (isCurrentlyCheckedIn) {
      setJenis('Pulang');
      setShift(lastTodayRecord?.shift || '');
      if (!cabang) setCabang(lastTodayRecord?.cabang || '');
    } else {
      setJenis('Masuk');
      setShift('');
    }
  }, [isCurrentlyCheckedIn, lastTodayRecord]);

  const handleAbsen = async () => {
    if (!photo || !shift || !cabang || !gps) return alert("Lengkapi data.");
    if (isInsideRadius === false) {
      alert(`ABSENSI DITOLAK: Anda berada di luar radius lokasi salon.`);
      return;
    }

    setLoading(true);
    try {
      const materiToSend = currentMateri?.bab || currentMateri?.judul || "Materi Umum";
      const distVal = Math.round(distance || 0);
      const statusLokasiFix = `${distVal} Meter`;

      const result = await api.absen({
        nama: user.nama, email: user.email, jenis, shift, cabang,
        lat: gps.lat, lng: gps.lng, accuracy: gps.accuracy,
        jarak: distVal,
        foto: photo, 
        statusLokasi: statusLokasiFix, 
        materi: materiToSend
      });

      if (result.status === 'sukses') {
        setShowSuccessView(true);
      } else {
        alert(result.message || "Gagal absen.");
      }
    } catch (e) {
      alert("Kesalahan koneksi.");
    } finally {
      setLoading(false);
    }
  };

  const startCamera = async () => {
    if (isCameraOpen || photo) return;
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } });
      streamRef.current = stream;
      setIsCameraOpen(true);
      setTimeout(() => { if (videoRef.current) { videoRef.current.srcObject = stream; videoRef.current.play(); } }, 100);
    } catch (e) { alert("Akses kamera ditolak."); }
  };

  const takePhoto = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (videoRef.current && canvasRef.current) {
      const canvas = canvasRef.current;
      const video = videoRef.current;
      canvas.width = video.videoWidth; canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        setPhoto(canvas.toDataURL('image/jpeg', 0.8));
        if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
        setIsCameraOpen(false);
      }
    }
  };

  const resetPhoto = (e: React.MouseEvent) => {
    e.stopPropagation();
    setPhoto(null);
    setIsCameraOpen(false);
    startCamera();
  };

  const getLogs = (): GroupedHistory[] => {
    const groups: Record<string, GroupedHistory> = {};
    const monthNames = ["JAN", "FEB", "MAR", "APR", "MEI", "JUN", "JUL", "AGT", "SEP", "OKT", "NOV", "DES"];

    attendanceHistory.forEach(item => {
      const date = parseLocalDate(item.waktu);
      if (!date) return;
      const dStr = date.getDate().toString().padStart(2, '0');
      const mStr = (date.getMonth() + 1).toString().padStart(2, '0');
      const y = date.getFullYear();
      const mIdx = date.getMonth();
      const key = `${y}${mStr}${dStr}`; 

      if (!groups[key]) {
        groups[key] = {
          dateKey: key, 
          dateDisplay: `${dStr}/${mStr}/${y}`,
          shortDate: `${dStr} ${monthNames[mIdx]}`,
          monthYear: `${monthFullNames[mIdx]} ${y}`,
          cabang: item.cabang, shift: item.shift
        };
      }

      const timeHM = date.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }).replace('.', ':');

      if (item.jenis === 'Masuk' && !groups[key].masuk) {
        groups[key].masuk = timeHM;
        const [h, min] = timeHM.split(':').map(Number);
        if (item.shift === 'Pagi' || item.shift === 'Full Day') {
           groups[key].status = (h > 8 || (h === 8 && min > 35)) ? 'TELAT' : 'TEPAT WAKTU';
        } else if (item.shift === 'Siang') {
           groups[key].status = (h > 12 || (h === 12 && min > 35)) ? 'TELAT' : 'TEPAT WAKTU';
        } else {
           groups[key].status = 'TEPAT WAKTU';
        }
      } else if (item.jenis === 'Pulang' && !groups[key].pulang) {
        groups[key].pulang = timeHM;
      }
    });

    const all = Object.values(groups) as GroupedHistory[];
    all.sort((a, b) => b.dateKey.localeCompare(a.dateKey));
    return selectedMonth ? all.filter(d => d.monthYear === selectedMonth) : all;
  };

  const logs = getLogs(); // logs ini SUDAH difilter sesuai selectedMonth (misal Januari)

  // STATISTIK PERHITUNGAN
  const totalHadirUnique = logs.length; 
  const totalTepat = logs.filter(l => l.status === 'TEPAT WAKTU').length;
  const totalTelat = logs.filter(l => l.status === 'TELAT').length;

  // LOGIKA HITUNG LIBUR YANG DIPERBAIKI (REV 2)
  // Menambahkan pengurangan jatah libur mingguan
  let totalLibur = 0;

  if (selectedMonth) {
    const parts = selectedMonth.split(' ');
    // parts[0] = Nama Bulan (Januari), parts[1] = Tahun (2026)
    const mIdx = monthFullNames.indexOf(parts[0]);
    const mYear = parseInt(parts[1]);

    if (mIdx !== -1 && !isNaN(mYear)) {
      // 1. Hitung jumlah hari dalam bulan tersebut (misal Jan = 31, Feb 2024 = 29)
      const daysInMonth = new Date(mYear, mIdx + 1, 0).getDate();

      // 2. Tentukan Tanggal Mulai (Start Date)
      // Default tanggal 1, tapi kalau ada Join Date, gunakan tanggal join (jika bulan sama)
      let startDay = 1;

      if (joinDate) {
        const jDate = parseLocalDate(joinDate);
        if (jDate) {
           // Jika bergabung di tahun dan bulan yang sama dengan filter
           if (jDate.getFullYear() === mYear && jDate.getMonth() === mIdx) {
              startDay = jDate.getDate();
           } 
           // Jika bergabung SETELAH bulan yang dipilih (misal gabung Feb, lihat Jan), maka libur 0
           else if (jDate > new Date(mYear, mIdx + 1, 0)) {
              startDay = 999; // Flag untuk set libur 0
           }
        }
      }

      // 3. Tentukan Tanggal Akhir (End Date)
      // Jika bulan yang dipilih ADALAH bulan ini, hitung sampai hari ini.
      // Jika bulan lalu, hitung sampai akhir bulan.
      let endDay = daysInMonth;
      const nowReal = new Date();

      if (nowReal.getFullYear() === mYear && nowReal.getMonth() === mIdx) {
         endDay = nowReal.getDate();
      } else if (nowReal < new Date(mYear, mIdx, 1)) {
         // Kalau pilih bulan depan (future), endDay 0
         endDay = 0;
      }

      if (startDay <= endDay) {
        const totalDaysPeriod = endDay - startDay + 1;

        // 4. Hitung jatah libur (1 hari per minggu)
        // Rumus sederhana: Floor(TotalHari / 7)
        // Contoh: Jan 15-31 (17 hari) -> 17/7 = 2.42 -> 2 hari jatah libur.
        const weeklyOffs = Math.floor(totalDaysPeriod / 7);

        const expectedPresence = totalDaysPeriod - weeklyOffs;

        // Total Libur (Absen/Alpha) = Ekspektasi - Realisasi
        totalLibur = Math.max(0, expectedPresence - totalHadirUnique);
      } else {
        totalLibur = 0;
      }
    }
  }

  const disciplineRate = totalHadirUnique > 0 ? Math.round((totalTepat / totalHadirUnique) * 100) : 0;
  // Progress kehadiran (visualisasi bar)
  // Untuk bulan lalu, 100% jika hadir > 24 hari (asumsi). Untuk bulan berjalan, relatif.
  const attendanceProgress = Math.min(100, Math.round((totalHadirUnique / 26) * 100));

  // Opsi Dropdown Bulan (Generate dari history + Bulan Ini)
  const months = Array.from(new Set(attendanceHistory.map(item => {
    const date = parseLocalDate(item.waktu);
    if (!date) return "";
    return `${monthFullNames[date.getMonth()]} ${date.getFullYear()}`;
  }))).filter(m => m !== "");

  if (!months.includes(currentMonthYearFilter)) {
    months.unshift(currentMonthYearFilter);
  }

  if (showSuccessView) {
    return (
      <div className="relative z-20 min-h-[60vh] flex flex-col items-center justify-center animate-in fade-in zoom-in duration-500 max-w-lg mx-auto px-4">
           <div className="glass-card p-10 !rounded-[3rem] w-full text-center space-y-8 bg-black/20 border-2 border-emerald-500/30 shadow-[0_0_50px_rgba(52,211,153,0.2)]">
              <div className="w-24 h-24 rounded-full bg-emerald-500/20 flex items-center justify-center mx-auto mb-4 border border-emerald-500/50 shadow-[0_0_30px_rgba(52,211,153,0.3)]">
                <CheckCircleIcon size={50} className="text-emerald-400" />
              </div>
              <div className="space-y-4">
                 <h3 className="text-3xl font-black text-white uppercase tracking-tight leading-none">Absensi<br/>Berhasil!</h3>
                 <p className="text-emerald-glow text-xs font-black tracking-widest uppercase">Data Tersimpan</p>
                 <p className="text-white/60 text-xs font-medium leading-relaxed px-2">
                   Terima kasih atas dedikasi Anda hari ini. Selamat bekerja dan berikan yang terbaik!
                 </p>
              </div>
              <button 
                onClick={() => {
                  setShowSuccessView(false);
                  onAttendanceSuccess(); 
                }}
                className="glass-button w-full !rounded-2xl active-emerald-tab mt-2"
              >
                LANJUT KE MATERI
              </button>
           </div>
      </div>
    );
  }

  return (
    <div className="relative z-20 space-y-8 animate-in fade-in duration-700 max-w-lg mx-auto pb-32 px-4">
      <div className="flex items-center glass-card p-1 !rounded-full h-14 bg-black/40">
        <button onClick={() => setActiveView('absen')} className={`flex-1 h-12 rounded-full text-[10px] font-black uppercase tracking-widest ${activeView === 'absen' ? 'active-emerald-tab' : 'text-white/30'}`}>Absensi</button>
        <button onClick={() => setActiveView('laporan')} className={`flex-1 h-12 rounded-full text-[10px] font-black uppercase tracking-widest ${activeView === 'laporan' ? 'active-emerald-tab' : 'text-white/30'}`}>Riwayat</button>
      </div>

      {activeView === 'absen' ? (
        <div className="space-y-6 flex flex-col items-center">
          <header className="text-center w-full">
            <h2 className="text-3xl font-black tracking-normal text-white">Presensi Digital</h2>
            <p className="text-emerald-glow text-[11px] uppercase font-black mt-2 tracking-[0.4em]">{currentTime.toLocaleTimeString('id-ID')}</p>
          </header>

          <div className="glass-card p-8 !rounded-[2.5rem] space-y-6 bg-black/20 w-full text-left">
            <div className="flex gap-2">
              <button disabled={isCurrentlyCheckedIn} onClick={() => setJenis('Masuk')} className={`flex-1 py-4 rounded-xl text-[10px] font-black uppercase ${jenis === 'Masuk' ? 'active-emerald-tab' : 'bg-white/5 opacity-40'}`}>Masuk {isCurrentlyCheckedIn && "✓"}</button>
              <button disabled={!isCurrentlyCheckedIn} onClick={() => setJenis('Pulang')} className={`flex-1 py-4 rounded-xl text-[10px] font-black uppercase ${jenis === 'Pulang' ? 'active-emerald-tab' : 'bg-white/5 opacity-40'}`}>Pulang</button>
            </div>

            <div className="space-y-5">
              <div className="space-y-2 w-full">
                <label className="text-[10px] opacity-60 uppercase ml-2 font-black text-white tracking-widest">Shift Kerja</label>
                <select value={shift} onChange={(e) => setShift(e.target.value)} disabled={isCurrentlyCheckedIn} className="glass-input !h-14 !rounded-xl text-[11px] font-bold">
                  <option value="">-- Pilih Shift --</option>
                  <option value="Pagi">Pagi (08:30-17:00)</option>
                  <option value="Siang">Siang (12:30-21:00)</option>
                  <option value="Full Day">Full Day (08:30-21:00)</option>
                </select>
              </div>

              <div className="space-y-2 w-full">
                <label className="text-[10px] opacity-60 uppercase ml-2 font-black text-white tracking-widest">Lokasi Cabang</label>
                <select value={cabang} onChange={(e) => setCabang(e.target.value)} className="glass-input !h-14 !rounded-xl text-sm font-bold">
                  <option value="">-- Pilih Lokasi --</option>
                  {lokasiData.map((l: any, i) => {
                    const n = String(l?.namacabang || l?.nama || l?.Nama || "Cabang Flow");
                    return <option key={i} value={n}>{n.toUpperCase()}</option>;
                  })}
                </select>
              </div>
            </div>

            {cabang && distance !== null && (
              <div className="pt-2 flex items-center justify-between px-2">
                <span className="text-[10px] font-black uppercase tracking-widest opacity-40 italic">Status Lokasi:</span>
                <span className={`text-[10px] font-black tracking-widest uppercase ${isInsideRadius ? 'text-emerald-400' : 'text-red-500'}`}>
                  {Math.round(distance)} Meter 
                  {isInsideRadius ? ' (DI AREA)' : ' (LUAR RADIUS)'}
                </span>
              </div>
            )}
          </div>

          <div className="flex flex-col items-center py-4 w-full relative">
            <div className="camera-circle-frame shadow-2xl relative mb-4" onClick={startCamera}>
              {isCameraOpen ? (
                <video ref={videoRef} autoPlay playsInline muted style={{ transform: 'scaleX(-1)' }} />
              ) : photo ? (
                <div className="relative w-full h-full">
                  <img src={photo} alt="Selfie" className="w-full h-full object-cover" />
                  <button onClick={resetPhoto} className="absolute bottom-6 left-1/2 -translate-x-1/2 w-12 h-12 glass-card !rounded-full flex items-center justify-center border border-white/20 active:scale-90 transition-transform bg-red-500/30 z-50 shadow-xl">
                    <svg className="w-6 h-6 text-red-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                    </svg>
                  </button>
                </div>
              ) : (
                <div className="text-center opacity-30 flex flex-col items-center">
                  <svg className="w-10 h-10 mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812-1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /></svg>
                  <p className="text-[10px] font-black uppercase tracking-widest">Klik Selfie</p>
                </div>
              )}
              {isCameraOpen && (
                <div className="absolute bottom-6 inset-x-0 flex justify-center z-10">
                  <button onClick={takePhoto} className="w-14 h-14 rounded-full border-[4px] border-emerald-400/50 bg-emerald-400/20 active:scale-95 transition-transform shadow-lg" />
                </div>
              )}
            </div>

            {isCameraOpen && (
              <p className="text-[10px] font-black text-emerald-glow uppercase tracking-[0.15em] animate-breathing leading-tight drop-shadow-xl text-center">
                PASTIKAN TERLIHAT <br/> FOTO DI DALAM SALON
              </p>
            )}
          </div>

          <button onClick={handleAbsen} disabled={loading || !photo || isInsideRadius === false} className={`glass-button w-full !rounded-2xl ${!photo || loading || isInsideRadius === false ? 'opacity-30' : 'active-emerald-tab'}`}>
            {loading ? "MENGIRIM..." : isInsideRadius === false ? "DILUAR RADIUS" : `KONFIRMASI ${jenis.toUpperCase()}`}
          </button>
        </div>
      ) : (
        <div className="space-y-8 pt-2 text-left">
          <div className="space-y-2 px-1">
             <div className="flex items-center justify-between">
                <label className="text-[9px] opacity-40 uppercase font-black text-white tracking-[0.3em] ml-1">Filter Periode</label>
                {isSyncing && <span className="text-[8px] text-emerald-glow font-black uppercase animate-pulse">Syncing...</span>}
