      ) : (
        <div className="space-y-8 pt-2 text-left">
          <div className="space-y-2 px-1">
             <div className="flex items-center justify-between">
                <label className="text-[9px] opacity-40 uppercase font-black text-white tracking-[0.3em] ml-1">Filter Periode</label>
                {isSyncing && <span className="text-[8px] text-emerald-glow font-black uppercase animate-pulse">Syncing...</span>}
             </div>
             <select value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} className="glass-input !h-14 !rounded-2xl text-[12px] font-black uppercase tracking-widest bg-black/60 border border-white/5 shadow-2xl">
               {months.length > 0 ? months.map((m, i) => <option key={i} value={m}>{m.toUpperCase()}</option>) : <option value="">BELUM ADA DATA</option>}
             </select>
          </div>

          <div className="glass-card p-8 !rounded-[2.5rem] bg-black/30 border border-white/5 space-y-8 shadow-2xl overflow-hidden px-10">
            <div className="flex items-center gap-8">
              <div className="relative w-32 h-32 shrink-0 flex items-center justify-center">
                 <svg viewBox="0 0 100 100" className="w-full h-full transform -rotate-90">
                    <circle cx="50" cy="50" r="42" stroke="rgba(255,255,255,0.05)" strokeWidth="8" fill="transparent" />
                    <circle 
                      cx="50" cy="50" r="42" stroke="#34d399" strokeWidth="8" fill="transparent" 
                      strokeDasharray="263.8" strokeDashoffset={263.8 * (1 - disciplineRate/100)} 
                      strokeLinecap="round" className="transition-all duration-1000 ease-out"
                    />
                 </svg>
                 <div className="absolute inset-0 flex items-center justify-center">
                    <span className="text-2xl font-black text-white italic tracking-tighter">{disciplineRate}%</span>
                 </div>
              </div>

              <div className="flex-1 space-y-2">
                 <p className="text-xl font-black text-white tracking-tight leading-none mb-1">Indeks Kedisplinan</p>
                 <p className="text-[11px] font-medium text-white/40 leading-snug lowercase">
                   {totalTepat}x tepat waktu dari {totalHadirUnique} hari kehadiran
                 </p>
                 <div className="space-y-1.5 pt-3">
                    <div className="flex justify-between text-[9px] font-black text-white/30 uppercase tracking-normal">
                       <span>KEHADIRAN</span>
                       <span className="text-emerald-glow">{attendanceProgress}%</span>
                    </div>
                    <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden">
                       <div className="h-full bg-emerald-400 rounded-full transition-all duration-1000" style={{ width: `${attendanceProgress}%` }} />
                    </div>
                 </div>
              </div>
            </div>

            <div className="grid grid-cols-3 pt-8 border-t border-white/5">
              <div className="text-center space-y-1">
                 <p className="text-[10px] font-black text-white/30 uppercase tracking-[0.2em]">Hadir</p>
                 <p className="text-3xl font-black text-white italic tracking-tighter">{totalHadirUnique}</p>
                 <p className="text-[8px] font-bold text-emerald-400/80 uppercase tracking-widest">Max: {maxHadir}</p>
              </div>
              <div className="text-center space-y-1 border-x border-white/5">
                 <p className="text-[10px] font-black text-white/30 uppercase tracking-[0.2em]">Libur</p>
                 <p className="text-3xl font-black text-white/50 italic tracking-tighter">{totalLibur}</p>
                 <p className="text-[8px] font-bold text-white/40 uppercase tracking-widest">Max: {allowedOffs}</p>
              </div>
              <div className="text-center space-y-1">
                 <p className="text-[10px] font-black text-white/30 uppercase tracking-[0.2em]">Telat</p>
                 <p className="text-3xl font-black text-red-400 italic tracking-tighter">{totalTelat}</p>
                 <p className="text-[8px] font-bold text-red-400/60 uppercase tracking-widest">Max: 0</p>
              </div>
            </div>
          </div>

          <div className="space-y-4 px-1">
            <label className="text-[10px] opacity-40 uppercase font-black text-white tracking-[0.3em] ml-1">Rekap Absensi</label>
            <div className="space-y-3">
               {logs.length > 0 ? logs.map((log, i) => (
                 <div key={i} className="glass-card px-8 py-5 !rounded-full bg-black/20 border border-white/5 flex items-center justify-between shadow-xl min-h-[70px]">
                    <div className="flex-[1.2] text-left min-w-0 pr-2">
                       <p className="text-[11px] font-black text-white italic uppercase tracking-tighter leading-tight">{log.shortDate}</p>
                       <p className="text-[10px] font-bold text-white/40 uppercase tracking-[0.1em] truncate w-full">{log.cabang || 'FLOW SALON'}</p>
                    </div>
                    <div className="flex-1 flex flex-col items-center justify-center text-center px-1">
                       <p className="text-[9px] font-black text-white/40 uppercase tracking-[0.1em]">SHIFT {String(log.shift || '').toUpperCase()}</p>
                       <p className={`text-[10px] font-black tracking-widest uppercase ${log.status === 'TEPAT WAKTU' ? 'text-emerald-400' : 'text-red-500'}`}>
                         {log.status === 'TEPAT WAKTU' ? 'TEPAT' : 'TELAT'}
                       </p>
                    </div>
                    <div className="flex-[0.8] flex flex-col items-end justify-center text-right pl-2">
                       <p className="text-[12px] font-black text-white/40 italic tracking-tighter">{log.masuk || '--:--'}</p>
                       <p className="text-[12px] font-black text-white/40 italic tracking-tighter">{log.pulang || '--:--'}</p>
                    </div>
                 </div>
               )) : <div className="py-20 text-center opacity-30 text-[10px] font-black uppercase tracking-widest">{isSyncing ? "LOADING..." : "RIWAYAT KOSONG"}</div>}
            </div>
          </div>
        </div>
      )}
      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { api } from '../services/apiService';
import { User } from '../types';
import { CheckCircleIcon } from '../components/Icons';

interface AttendanceProps {
  user: User;
  onAttendanceSuccess: () => void;
  lokasiData: any[];
  currentMateri: any; 
  joinDate?: string | null;
}

interface HistoryItem {
  waktu: string;
  jenis: string;
  cabang: string;
  shift: string;
}

interface GroupedHistory {
  dateKey: string;
  dateDisplay: string;
  shortDate: string;
  monthYear: string;
  cabang: string; 
  shift: string;
  masuk?: string;
  pulang?: string;
  status?: 'TEPAT WAKTU' | 'TELAT';
}

const calculateDistance = (lat1: number, lon1: number, lat2: number, lon2: number): number => {
  const R = 6371e3; // metres
  const φ1 = lat1 * Math.PI / 180;
  const φ2 = lat2 * Math.PI / 180;
  const Δφ = (lat2 - lat1) * Math.PI / 180;
  const Δλ = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(Δφ / 2) * Math.sin(Δφ / 2) + Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
};

const parseLocalDate = (dateStr: any): Date | null => {
  try {
    if (!dateStr) return null;
    if (dateStr instanceof Date) return isNaN(dateStr.getTime()) ? null : dateStr;

    const s = String(dateStr).trim();
    const nativeDate = new Date(s);
    if (!isNaN(nativeDate.getTime())) return nativeDate;

    const datePart = s.split(/[ ,T]+/)[0];
    const bits = datePart.split(/[\/\-\.]/);

    if (bits.length === 3) {
      let d, m, y;
      const b0 = parseInt(bits[0]);
      const b1 = parseInt(bits[1]);
      const b2 = parseInt(bits[2]);

      if (bits[2].length === 4) {
        if (b0 > 12) { d = b0; m = b1; y = b2; } 
        else { m = b0; d = b1; y = b2; }
      } else if (bits[0].length === 4) {
        y = b0; m = b1; d = b2;
      } else return null;

      const finalDate = new Date(y, m - 1, d);
      const timePart = s.split(/[ ,T]+/)[1];
      if (timePart) {
        const tBits = timePart.split(/[:\.]/);
        if (tBits.length >= 2) {
          finalDate.setHours(parseInt(tBits[0]), parseInt(tBits[1]), parseInt(tBits[2] || "0"));
        }
      }
      return isNaN(finalDate.getTime()) ? null : finalDate;
    }
    return null;
  } catch (e) { return null; }
};

export const Attendance: React.FC<AttendanceProps> = ({ user, onAttendanceSuccess, lokasiData, currentMateri, joinDate }) => {
  const [activeView, setActiveView] = useState<'absen' | 'laporan'>('absen');
  const [currentTime, setCurrentTime] = useState(new Date());
  const [jenis, setJenis] = useState('Masuk');
  const [shift, setShift] = useState('');
  const [cabang, setCabang] = useState('');
  const [photo, setPhoto] = useState<string | null>(null);
  const [isCameraOpen, setIsCameraOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [gps, setGps] = useState<{ lat: number, lng: number, accuracy: number } | null>(null);
  const [attendanceHistory, setAttendanceHistory] = useState<HistoryItem[]>([]);

  const [showSuccessView, setShowSuccessView] = useState(false);

  const now = new Date();
  const monthFullNames = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
  const currentMonthYearFilter = `${monthFullNames[now.getMonth()]} ${now.getFullYear()}`;
  const [selectedMonth, setSelectedMonth] = useState<string>(currentMonthYearFilter);
  const [isSyncing, setIsSyncing] = useState(false);

  const [distance, setDistance] = useState<number | null>(null);
  const [allowedRadius, setAllowedRadius] = useState<number>(100);
  const [isInsideRadius, setIsInsideRadius] = useState<boolean | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    const forceView = localStorage.getItem('force_attendance_view');
    if (forceView === 'laporan') {
      setActiveView('laporan');
      localStorage.removeItem('force_attendance_view');
    }
  }, []);

  useEffect(() => {
    const fetchHistory = async () => {
      setIsSyncing(true);
      try {
        const history = await api.getAttendanceHistory(user.email);
        if (history && Array.isArray(history)) {
          const sorted = [...history].sort((a, b) => new Date(a.waktu).getTime() - new Date(b.waktu).getTime());
          setAttendanceHistory(sorted);
        }
      } catch (err) {
        console.error("Gagal ambil history:", err);
      } finally {
        setIsSyncing(false);
      }
    };
    fetchHistory();
  }, [user.email, activeView]);

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    if (navigator.geolocation) {
      const watcher = navigator.geolocation.watchPosition(
        (pos) => setGps({ lat: pos.coords.latitude, lng: pos.coords.longitude, accuracy: pos.coords.accuracy }),
        (err) => console.error(err), 
        { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
      );
      return () => {
        navigator.geolocation.clearWatch(watcher);
        clearInterval(timer);
      };
    }
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    if (gps && cabang && lokasiData.length > 0) {
      const targetCabang = lokasiData.find(l => {
        const nameInSheet = String(l?.namacabang || l?.nama || l?.Nama || "").toUpperCase();
        return nameInSheet === cabang.toUpperCase();
      });

      if (targetCabang) {
        const latTarget = parseFloat(targetCabang.latitude || targetCabang.lat);
        const lngTarget = parseFloat(targetCabang.longitude || targetCabang.lng);
        const radiusTarget = parseFloat(targetCabang.radiusmeter || targetCabang.radius || 100);
        if (!isNaN(latTarget) && !isNaN(lngTarget)) {
          const dist = calculateDistance(gps.lat, gps.lng, latTarget, lngTarget);
          setDistance(dist);
          setAllowedRadius(radiusTarget);
          setIsInsideRadius(dist <= radiusTarget);
        } else {
          setDistance(null);
          setIsInsideRadius(true);
        }
      }
    }
  }, [gps, cabang, lokasiData]);

  const lastTodayRecord = [...attendanceHistory].reverse().find(h => {
    const date = parseLocalDate(h.waktu);
    return date && date.toDateString() === new Date().toDateString();
  });

  const isCurrentlyCheckedIn = lastTodayRecord?.jenis === 'Masuk';

  useEffect(() => {
    if (isCurrentlyCheckedIn) {
      setJenis('Pulang');
      setShift(lastTodayRecord?.shift || '');
      if (!cabang) setCabang(lastTodayRecord?.cabang || '');
    } else {
      setJenis('Masuk');
      setShift('');
    }
  }, [isCurrentlyCheckedIn, lastTodayRecord]);

  const handleAbsen = async () => {
    if (!photo || !shift || !cabang || !gps) return alert("Lengkapi data.");
    if (isInsideRadius === false) {
      alert(`ABSENSI DITOLAK: Anda berada di luar radius lokasi salon.`);
      return;
    }

    setLoading(true);
    try {
      const materiToSend = currentMateri?.bab || currentMateri?.judul || "Materi Umum";
      const distVal = Math.round(distance || 0);
      const statusLokasiFix = `${distVal} Meter`;

      const result = await api.absen({
        nama: user.nama, email: user.email, jenis, shift, cabang,
        lat: gps.lat, lng: gps.lng, accuracy: gps.accuracy,
        jarak: distVal,
        foto: photo, 
        statusLokasi: statusLokasiFix, 
        materi: materiToSend
      });

      if (result.status === 'sukses') {
        setShowSuccessView(true);
      } else {
        alert(result.message || "Gagal absen.");
      }
    } catch (e) {
      alert("Kesalahan koneksi.");
    } finally {
      setLoading(false);
    }
  };

  const startCamera = async () => {
    if (isCameraOpen || photo) return;
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } });
      streamRef.current = stream;
      setIsCameraOpen(true);
      setTimeout(() => { if (videoRef.current) { videoRef.current.srcObject = stream; videoRef.current.play(); } }, 100);
    } catch (e) { alert("Akses kamera ditolak."); }
  };

  const takePhoto = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (videoRef.current && canvasRef.current) {
      const canvas = canvasRef.current;
      const video = videoRef.current;
      canvas.width = video.videoWidth; canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        setPhoto(canvas.toDataURL('image/jpeg', 0.8));
        if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
        setIsCameraOpen(false);
      }
    }
  };

  const resetPhoto = (e: React.MouseEvent) => {
    e.stopPropagation();
    setPhoto(null);
    setIsCameraOpen(false);
    startCamera();
  };

  const getLogs = (): GroupedHistory[] => {
    const groups: Record<string, GroupedHistory> = {};
    const monthNames = ["JAN", "FEB", "MAR", "APR", "MEI", "JUN", "JUL", "AGT", "SEP", "OKT", "NOV", "DES"];

    attendanceHistory.forEach(item => {
      const date = parseLocalDate(item.waktu);
      if (!date) return;
      const dStr = date.getDate().toString().padStart(2, '0');
      const mStr = (date.getMonth() + 1).toString().padStart(2, '0');
      const y = date.getFullYear();
      const mIdx = date.getMonth();
      const key = `${y}${mStr}${dStr}`; 

      if (!groups[key]) {
        groups[key] = {
          dateKey: key, 
          dateDisplay: `${dStr}/${mStr}/${y}`,
          shortDate: `${dStr} ${monthNames[mIdx]}`,
          monthYear: `${monthFullNames[mIdx]} ${y}`,
          cabang: item.cabang, shift: item.shift
        };
      }

      const timeHM = date.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }).replace('.', ':');

      if (item.jenis === 'Masuk' && !groups[key].masuk) {
        groups[key].masuk = timeHM;
        const [h, min] = timeHM.split(':').map(Number);
        if (item.shift === 'Pagi' || item.shift === 'Full Day') {
           groups[key].status = (h > 8 || (h === 8 && min > 35)) ? 'TELAT' : 'TEPAT WAKTU';
        } else if (item.shift === 'Siang') {
           groups[key].status = (h > 12 || (h === 12 && min > 35)) ? 'TELAT' : 'TEPAT WAKTU';
        } else {
           groups[key].status = 'TEPAT WAKTU';
        }
      } else if (item.jenis === 'Pulang' && !groups[key].pulang) {
        groups[key].pulang = timeHM;
      }
    });

    const all = Object.values(groups) as GroupedHistory[];
    all.sort((a, b) => b.dateKey.localeCompare(a.dateKey));
    return selectedMonth ? all.filter(d => d.monthYear === selectedMonth) : all;
  };

  const logs = getLogs(); // logs ini SUDAH difilter sesuai selectedMonth (misal Januari)

  // STATISTIK PERHITUNGAN
  const totalHadirUnique = logs.length; 
  const totalTepat = logs.filter(l => l.status === 'TEPAT WAKTU').length;
  const totalTelat = logs.filter(l => l.status === 'TELAT').length;

  // LOGIKA HITUNG LIBUR YANG DIPERBAIKI (REV 4)
  // Memisahkan perhitungan "Max Quota (Sebulan Penuh)" vs "Realisasi (Sampai Hari Ini)"

  let totalLibur = 0; // Ini adalah "Realisasi Libur/Alpha" (Big Number)
  let maxHadir = 0;   // Ini adalah "Quota Hadir Sebulan" (Small Label)
  let allowedOffs = 0; // Ini adalah "Quota Libur Sebulan" (Small Label)

  if (selectedMonth) {
    const parts = selectedMonth.split(' ');
    const mIdx = monthFullNames.indexOf(parts[0]);
    const mYear = parseInt(parts[1]);

    if (mIdx !== -1 && !isNaN(mYear)) {
      // 1. Setup Tanggal
      const daysInMonth = new Date(mYear, mIdx + 1, 0).getDate();

      // Determine Start Day (Join Date Logic)
      let startDay = 1;
      if (joinDate) {
        const jDate = parseLocalDate(joinDate);
        if (jDate) {
           if (jDate.getFullYear() === mYear && jDate.getMonth() === mIdx) {
              startDay = jDate.getDate();
           } else if (jDate > new Date(mYear, mIdx + 1, 0)) {
              startDay = 999; // Not joined yet
           }
        }
      }

      // ------------------------------------------------------------------
      // A. PERHITUNGAN KUOTA (POTENTIAL/FULL MONTH) -> Untuk Label "Max"
      // ------------------------------------------------------------------
      if (startDay <= daysInMonth) {
         const potentialDays = daysInMonth - startDay + 1;
         // Jatah Libur: 1 hari per minggu
         allowedOffs = Math.floor(potentialDays / 7);
         // Target Hadir
         maxHadir = potentialDays - allowedOffs;
      } else {
         allowedOffs = 0;
         maxHadir = 0;
      }

      // ------------------------------------------------------------------
      // B. PERHITUNGAN REALISASI (ELAPSED TIME) -> Untuk Big Number "Libur"
      // ------------------------------------------------------------------
      let elapsedEndDay = daysInMonth;
      const nowReal = new Date();

      // Jika bulan yang dipilih adalah bulan saat ini, batasi sampai hari ini (current date)
      if (nowReal.getFullYear() === mYear && nowReal.getMonth() === mIdx) {
         elapsedEndDay = nowReal.getDate();
      } else if (nowReal < new Date(mYear, mIdx, 1)) {
         // Jika bulan depan, elapsed = 0
         elapsedEndDay = 0;
      }

      // Hitung ekspektasi kehadiran sampai tanggal 'elapsedEndDay'
      if (startDay <= elapsedEndDay) {
        const elapsedDays = elapsedEndDay - startDay + 1;
        const elapsedAllowedOffs = Math.floor(elapsedDays / 7);
        const expectedHadirToDate = elapsedDays - elapsedAllowedOffs;

        // Libur (Alpha) = Ekspektasi - Realisasi
        totalLibur = Math.max(0, expectedHadirToDate - totalHadirUnique);
      } else {
        totalLibur = 0;
      }
    }
  }

  const disciplineRate = totalHadirUnique > 0 ? Math.round((totalTepat / totalHadirUnique) * 100) : 0;
