    const action = e.parameter.action;

    // FITUR LUPA PASSWORD
    if (action === 'forgot_password') {
      const email = (e.parameter.email || "").trim().toLowerCase();
      if (!email) return response({ status: 'error', message: 'Email tidak boleh kosong' });

      const users = getSheetData('Karyawan');
      const user = users.find(u => (u.email || "").toString().toLowerCase().trim() === email);

      if (user) {
        try {
          MailApp.sendEmail({
            to: user.email,
            subject: "Pemulihan Password - Flow Salon Portal",
            body: `Halo ${user.nama},\n\nPassword Anda adalah: ${user.password}\n\nSalam,\nFlow Salon IT`
          });
          return response({ status: 'sukses', message: 'Password telah dikirim ke emailmu.' });
        } catch (mailErr) {
          return response({ status: 'error', message: 'Gagal kirim email: ' + mailErr.toString() });
        }
      } else {
        return response({ status: 'error', message: 'Masukkan email yang terdaftar.' });
      }
    }

    if (action === 'get_initial_data') {
      const email = (e.parameter.email || "").toLowerCase().trim();

      const materiList = getSheetData('Materi'); 

      // LOGIKA BARU: Ambil Join Date dari Sheet Karyawan dengan PENGECEKAN EKSTRA
      let joinDate = null;
      if (email) {
