        const emp = employees.find(u => (u.email || "").toString().toLowerCase().trim() === email);
        if (emp) {
          // Cek berbagai kemungkinan nama kolom karena getSheetData menormalisasi header
          // Prioritas: timestamp -> waktu -> tanggal_masuk
          joinDate = emp.timestamp || emp.Timestamp || emp.waktu || emp.Waktu || null;

          // Pastikan format date ISO jika masih object Date
          if (joinDate instanceof Date) {
            joinDate = joinDate.toISOString();
          }
        }
      }

      let lastLog = null;
      if (email) {
        const allSheets = SS.getSheets();
        const absenSheets = allSheets.filter(s => s.getName().startsWith("Absensi_"));
        absenSheets.sort((a, b) => b.getName().localeCompare(a.getName()));

        for (const sheet of absenSheets) {
          const data = getSheetData(sheet.getName());
          const userLogs = data.filter(row => (row.email || "").toString().toLowerCase() === email);
          if (userLogs.length > 0) {
            const lastEntry = userLogs[userLogs.length - 1];
            lastLog = {
              waktu: lastEntry.waktu,
              materi: lastEntry.progress_materi || "" 
            };
            break; 
          }
