function saveFileToDrive(base64Data, folderId, fileName) {
  try {
    const splitData = base64Data.split(',');
    const contentType = splitData[0].match(/:(.*?);/)[1];
    const byteData = Utilities.base64Decode(splitData[1]);
    const blob = Utilities.newBlob(byteData, contentType, fileName);
    const folder = DriveApp.getFolderById(folderId);
    const file = folder.createFile(blob);
    file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
    return file.getUrl();
  } catch (e) { return "Error: " + e.toString(); }
}

function response(obj) {
  return ContentService.createTextOutput(JSON.stringify(obj)).setMimeType(ContentService.MimeType.JSON);
}

/**
 * HELPER GET SHEET DATA - DENGAN DUAL COMPATIBILITY
 * Mengembalikan objek dengan key ASLI (untuk app lain) DAN key lowercase (untuk app ini).
 */
function getSheetData(name) {
  const sheet = SS.getSheetByName(name);
  if (!sheet) return [];
  const values = sheet.getDataRange().getValues();
  if (values.length < 2) return [];
  const headers = values.shift();

  return values.map(row => {
    const obj = {};
    headers.forEach((h, i) => {
      let val = row[i];

      // Pastikan Date selalu jadi ISO String agar konsisten di JSON
      if (val instanceof Date) {
        // Cek validitas date
        if (!isNaN(val.getTime())) {
          val = val.toISOString();
        } else {
          val = ""; // Date invalid jadi string kosong
        }
      }

      // 1. Simpan Key ASLI (Original Case)
      // Ini menjaga agar aplikasi lain yang cari user['Nama'] tetap jalan
      obj[h] = val;

      // 2. Simpan Key LOWERCASE (Normalized)
      // Ini agar logika baru kita yang cari user['nama'] tetap jalan
      const cleanKey = h.toString().toLowerCase().trim().replace(/\s+/g, '_');
      if (cleanKey !== h.toString()) {
        obj[cleanKey] = val;
      }
    });
    return obj;
  });
}

