  const headers = values.shift();

  return values.map(row => {
    const obj = {};
    headers.forEach((h, i) => {
      const val = row[i]; // Val pasti string karena getDisplayValues()

      // 1. Simpan Key ASLI (Original Case) - Menjaga kompatibilitas App Lama
      // Contoh: obj['Timestamp'] = "1/27/2026 12:32:00"
      obj[h] = val;

      // 2. Simpan Key LOWERCASE (Normalized) - Untuk App Baru
      // Contoh: obj['timestamp'] = "1/27/2026 12:32:00"
      const cleanKey = h.toString().toLowerCase().trim().replace(/\s+/g, '_');
      if (cleanKey !== h.toString()) {
        obj[cleanKey] = val;
      }
    });
    return obj;
  });
}

