const SS = SpreadsheetApp.getActiveSpreadsheet();

/** 
 * KONFIGURASI FOLDER GOOGLE DRIVE
 */
const FOLDER_ID_ABSEN = "1D8JdT_X6KEeIkk8gVODLWm50UqtaYxS3"; 
const FOLDER_ID_KTP = "1g0d7zV9jbv-WEsVX1nrRi3B_ZsGnSTeW";

/**
 * PENTING: JALANKAN FUNGSI INI SEKALI SECARA MANUAL UNTUK MEMICU IZIN EMAIL
 * Pilih 'authorizeScript' di toolbar atas, lalu klik Run.
 */
function authorizeScript() {
  console.log("Memicu permintaan izin...");
  const email = Session.getActiveUser().getEmail();
  MailApp.getRemainingDailyQuota(); 
  console.log("Izin berhasil diberikan.");
}

function doGet(e) {
  if (!e || !e.parameter) {
    return ContentService.createTextOutput(JSON.stringify({
      status: 'sukses',
      message: 'Server backend berjalan.'
    })).setMimeType(ContentService.MimeType.JSON);
  }

  try {
    const action = e.parameter.action;

    // FITUR LUPA PASSWORD
    if (action === 'forgot_password') {
      const email = (e.parameter.email || "").trim().toLowerCase();
      if (!email) return response({ status: 'error', message: 'Email tidak boleh kosong' });

      const users = getSheetData('Karyawan');
      // Cari user (mendukung key 'email' atau 'Email')
      const user = users.find(u => (u.email || u.Email || "").toString().toLowerCase().trim() === email);

      if (user) {
        try {
          const pass = user.password || user.Password;
          const nama = user.nama || user.Nama;
          MailApp.sendEmail({
            to: (user.email || user.Email),
            subject: "Pemulihan Password - Flow Salon Portal",
            body: `Halo ${nama},\n\nPassword Anda adalah: ${pass}\n\nSalam,\nFlow Salon IT`
          });
          return response({ status: 'sukses', message: 'Password telah dikirim ke emailmu.' });
        } catch (mailErr) {
          return response({ status: 'error', message: 'Gagal kirim email: ' + mailErr.toString() });
        }
      } else {
        return response({ status: 'error', message: 'Masukkan email yang terdaftar.' });
      }
    }

    if (action === 'get_initial_data') {
      const email = (e.parameter.email || "").toLowerCase().trim();

      const materiList = getSheetData('Materi'); 

      // LOGIKA BARU: Ambil Join Date dari Sheet Karyawan
      let joinDate = null;
      if (email) {
        const employees = getSheetData('Karyawan');
        const emp = employees.find(u => (u.email || u.Email || "").toString().toLowerCase().trim() === email);
        if (emp) {
          // Cek berbagai kemungkinan nama kolom (Original & Lowercase)
          // Data yang diambil via getDisplayValues sudah berbentuk string (e.g. "1/27/2026")
          joinDate = emp.timestamp || emp.Timestamp || emp.waktu || emp.Waktu || emp.tanggal_masuk || null;
        }
      }

      let lastLog = null;
      if (email) {
        const allSheets = SS.getSheets();
        const absenSheets = allSheets.filter(s => s.getName().startsWith("Absensi_"));
        absenSheets.sort((a, b) => b.getName().localeCompare(a.getName()));

        for (const sheet of absenSheets) {
          const data = getSheetData(sheet.getName());
          const userLogs = data.filter(row => (row.email || row.Email || "").toString().toLowerCase() === email);
          if (userLogs.length > 0) {
            const lastEntry = userLogs[userLogs.length - 1];
            lastLog = {
              waktu: lastEntry.waktu || lastEntry.Waktu,
              materi: lastEntry.progress_materi || lastEntry.Progress_Materi || "" 
            };
            break; 
          }
        }
      }

      return response({
        materiList: materiList, 
        lastLog: lastLog,
        joinDate: joinDate, 
        sop: getSheetData('SOP'),
        pesanManager: getSheetData('PesanManager')?.reverse()[0] || { pesan: "Selamat Bekerja!", nama: "Manager", jabatan: "Salon Manager" },
        tugasDef: getSheetData('TugasDef'), 
        lokasi: getSheetData('Lokasi'),
        tips: getSheetData('Tips')
      });
    }

    if (action === 'get_history') {
      const email = (e.parameter.email || "").toLowerCase();
      const allSheets = SS.getSheets();
      let history = [];

      allSheets.forEach(s => {
        if (s.getName().startsWith("Absensi_")) {
          const data = getSheetData(s.getName());
          const filtered = data.filter(row => (row.email || row.Email || "").toString().toLowerCase() === email);
          history = history.concat(filtered);
        }
      });

      // Sort desc (parse string date manually since we use getDisplayValues)
      history.sort((a, b) => {
        const tA = a.waktu || a.Waktu;
        const tB = b.waktu || b.Waktu;
        return new Date(tB).getTime() - new Date(tA).getTime();
      });
      return response(history);
    }

    if (action === 'get_checklist_history') {
      const email = (e.parameter.email || "").toLowerCase();
      const nama = (e.parameter.nama || "").toLowerCase();
      const allSheets = SS.getSheets();
      let history = [];

      allSheets.forEach(s => {
        if (s.getName().startsWith("Checklist_")) {
          const data = getSheetData(s.getName());
          const filtered = data.filter(row => 
            (row.email || row.Email || "").toString().toLowerCase() === email || 
            (row.nama || row.Nama || "").toString().toLowerCase() === nama
          );
          history = history.concat(filtered);
        }
      });
      return response(history);
    }

    if (action === 'login') {
      const email = (e.parameter.email || "").toLowerCase().trim();
      const pass = (e.parameter.pass || "").toString();
      const users = getSheetData('Karyawan');

      const user = users.find(u => {
        const uEmail = (u.email || u.Email || "").toString().toLowerCase().trim();
        const uPass = (u.password || u.Password || "").toString();
        return uEmail === email && uPass === pass;
      });

      if (user) {
        return response({ 
          status: 'sukses', 
          nama: user.nama || user.Nama, 
          email: user.email || user.Email, 
          jabatan: user.jabatan || user.Jabatan 
        });
      } else {
        return response({ status: 'error', message: 'Email atau Password salah' });
      }
    }

    return response({ status: 'error', message: 'Action tidak valid' });

  } catch (err) {
    return response({ status: 'error', message: 'Server Error: ' + err.toString() });
  }
}

function doPost(e) {
  try {
    const p = JSON.parse(e.postData.contents);
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth() + 1;
    const timeStr = Utilities.formatDate(now, "GMT+7", "yyyyMMdd_HHmm");

    let quarter = "Q1";
    if (month >= 4 && month <= 6) quarter = "Q2";
    else if (month >= 7 && month <= 9) quarter = "Q3";
    else if (month >= 10 && month <= 12) quarter = "Q4";

    if (p.type === 'signup') {
      const sheet = SS.getSheetByName('Karyawan');
      let ktpUrl = "No Photo";
      if (p.fotoKTP && p.fotoKTP.includes("base64")) {
        ktpUrl = saveFileToDrive(p.fotoKTP, FOLDER_ID_KTP, `KTP_${p.nama}_${timeStr}`);
      }
      sheet.appendRow([now, p.nama, p.email, p.password, p.jabatan, p.ttl, p.wa, ktpUrl, p.k_nama, p.k_hub, p.k_wa]);
      return response({ status: 'sukses' });
    }

    if (p.type === 'absen') {
      const sheetName = `Absensi_${year}_${quarter}`;
      let sheet = SS.getSheetByName(sheetName) || SS.insertSheet(sheetName);

      if (sheet.getLastRow() === 0) {
        sheet.appendRow(['Waktu', 'Nama', 'Email', 'Jenis', 'Shift', 'Cabang', 'GPS', 'Status_Lokasi', 'Link_Foto_Drive', 'Progress_Materi']);
        sheet.getRange(1, 1, 1, 10).setFontWeight("bold").setBackground("#d1fadf");
      }

      let fotoUrl = "No Photo";
      if (p.foto && p.foto.includes("base64")) {
        fotoUrl = saveFileToDrive(p.foto, FOLDER_ID_ABSEN, `ABSEN_${p.jenis}_${p.nama}_${timeStr}`);
      }

      const materiRead = p.materi || "-";

      sheet.appendRow([now, p.nama, p.email, p.jenis, p.shift, p.cabang, `${p.lat},${p.lng}`, p.statusLokasi, fotoUrl, materiRead]);
      return response({ status: 'sukses' });
    }

    if (p.type === 'tugas') {
      const sheetName = `Checklist_${year}_${quarter}`;
      let sheet = SS.getSheetByName(sheetName) || SS.insertSheet(sheetName);

      if (sheet.getLastRow() === 0) {
        sheet.appendRow(['Waktu', 'Nama', 'Jabatan', 'Jenis_Checklist', 'Ringkasan', 'Skor_%', 'Data_Laporan_JSON']);
        sheet.getRange(1, 1, 1, 7).setFontWeight("bold").setBackground("#e0f2fe");
      }

      const ringkasan = `${p.totalSelesai} dari ${p.totalTugas} selesai`;
      const skor = p.totalTugas > 0 ? (p.totalSelesai / p.totalTugas) * 100 : 0;

      sheet.appendRow([now, p.nama, p.jabatan, p.jenis, ringkasan, skor.toFixed(0) + "%", JSON.stringify(p.checklist)]);
      return response({ status: 'sukses' });
    }

    return response({ status: 'error', message: 'Invalid Post Type' });
  } catch (err) {
    return response({ status: 'error', message: 'Post Error: ' + err.toString() });
  }
}

function saveFileToDrive(base64Data, folderId, fileName) {
  try {
    const splitData = base64Data.split(',');
    const contentType = splitData[0].match(/:(.*?);/)[1];
    const byteData = Utilities.base64Decode(splitData[1]);
    const blob = Utilities.newBlob(byteData, contentType, fileName);
    const folder = DriveApp.getFolderById(folderId);
    const file = folder.createFile(blob);
    file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
    return file.getUrl();
  } catch (e) { return "Error: " + e.toString(); }
}

function response(obj) {
  return ContentService.createTextOutput(JSON.stringify(obj)).setMimeType(ContentService.MimeType.JSON);
}

/**
 * HELPER GET SHEET DATA - DENGAN DUAL COMPATIBILITY + WYSIWYG
 * Menggunakan getDisplayValues() untuk menjamin format data string persis seperti di Sheet.
 * Mengembalikan objek dengan key ASLI (untuk app lama) DAN key lowercase (untuk app baru).
 */
function getSheetData(name) {
  const sheet = SS.getSheetByName(name);
  if (!sheet) return [];
  // PENTING: Gunakan getDisplayValues() agar data yang diambil persis string yang tampil di sheet (WYSIWYG)
  // Ini mencegah konversi Date otomatis ke ISO string yang bisa merusak aplikasi lama yang mengharapkan format dd/mm/yyyy dll.
  const values = sheet.getDataRange().getDisplayValues();
