const calculateDistance = (lat1: number, lon1: number, lat2: number, lon2: number): number => {
  const R = 6371e3; // metres
  const φ1 = lat1 * Math.PI / 180;
  const φ2 = lat2 * Math.PI / 180;
  const Δφ = (lat2 - lat1) * Math.PI / 180;
  const Δλ = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(Δφ / 2) * Math.sin(Δφ / 2) + Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
};

// Fungsi parsing tanggal helper yang robust terhadap string dari getDisplayValues
const parseDateHelper = (dateStr: any): Date | null => {
  try {
    if (!dateStr) return null;
    if (dateStr instanceof Date) return isNaN(dateStr.getTime()) ? null : dateStr;

    const s = String(dateStr).trim();

    // 1. Coba parse ISO standar dulu
    const isoDate = new Date(s);
    if (!isNaN(isoDate.getTime()) && s.includes('-') && s.includes('T')) return isoDate;

    // 2. Parse manual "DD/MM/YYYY" atau "MM/DD/YYYY"
    // Split berdasarkan pemisah umum
    const datePart = s.split(/[ ,T]+/)[0];
    const bits = datePart.split(/[\/\-\.]/);

    if (bits.length === 3) {
      let d, m, y;
      const b0 = parseInt(bits[0]);
      const b1 = parseInt(bits[1]);
      const b2 = parseInt(bits[2]);

      // Deteksi posisi tahun (4 digit)
      if (String(bits[2]).length === 4) {
        // Format XX/XX/YYYY
        // Logika deteksi DD/MM vs MM/DD:
        // Jika angka pertama > 12, pasti Tanggal (DD/MM/YYYY)
        if (b0 > 12) { 
           d = b0; m = b1; y = b2; 
        } else { 
           // Jika <= 12, prioritas MM/DD/YYYY (US) atau DD/MM/YYYY (ID)
           // Mengingat user di Indonesia, seringkali DD/MM, tapi Sheet default sering US.
           // Kita gunakan asumsi: Jika b1 > 12, maka b1 pasti tanggal -> MM/DD/YYYY
           if (b1 > 12) {
             m = b0; d = b1; y = b2;
           } else {
             // Ambigu (misal 1/2/2026). Default ke MM/DD/YYYY agar konsisten dengan sheet default
             m = b0; d = b1; y = b2;
           }
        }
      } else if (String(bits[0]).length === 4) { 
        // Format YYYY/MM/DD
        y = b0; m = b1; d = b2; 
      } else {
        // Fallback ke Date constructor biasa jika format lain (misal "27 Jan 2026")
        const fallback = new Date(s);
        return isNaN(fallback.getTime()) ? null : fallback;
      }

      const finalDate = new Date(y, m - 1, d);
      return isNaN(finalDate.getTime()) ? null : finalDate;
    }

    // 3. Fallback terakhir
    const finalFallback = new Date(s);
    return isNaN(finalFallback.getTime()) ? null : finalFallback;
  } catch (e) { return null; }
};

