const toTitleCase = (str: string) => {
  return str.replace(/\w\S*/g, (txt) => {
    return txt.charAt(0).toUpperCase() + txt.substr(1).toLowerCase();
  });
};

const parseDateSafe = (dateStr: any): Date | null => {
  try {
    if (!dateStr) return null;
    if (dateStr instanceof Date) return isNaN(dateStr.getTime()) ? null : dateStr;

    const s = String(dateStr).trim();

    // 1. Coba parse ISO
    const isoDate = new Date(s);
    if (!isNaN(isoDate.getTime()) && s.includes('-') && s.includes('T')) return isoDate;

    // 2. Parse manual numeric format (M/D/Y or D/M/Y)
    const datePart = s.split(/[ ,T]+/)[0];
    const bits = datePart.split(/[\/\-\.]/);
    if (bits.length === 3) {
      let d, m, y;
      const b0 = parseInt(bits[0]);
      const b1 = parseInt(bits[1]);
      const b2 = parseInt(bits[2]);

      // Jika tahun di belakang (XX/XX/YYYY)
      if (String(bits[2]).length === 4) {
        if (b0 > 12) { d = b0; m = b1; y = b2; } 
        else if (b1 > 12) { m = b0; d = b1; y = b2; }
        else { m = b0; d = b1; y = b2; } // Default MM/DD/YYYY
      } else if (String(bits[0]).length === 4) {
        y = b0; m = b1; d = b2;
      } else {
        const fallback = new Date(s);
        return isNaN(fallback.getTime()) ? null : fallback;
      }

      const finalDate = new Date(y, m - 1, d);
      return isNaN(finalDate.getTime()) ? null : finalDate;
    }

    // 3. Last resort
    const finalFallback = new Date(s);
    return isNaN(finalFallback.getTime()) ? null : finalFallback;
  } catch (e) { return null; }
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentPage, setCurrentPage] = useState<Page>(Page.Dashboard);
  const [showMateri, setShowMateri] = useState(false);
  const [isFocusMode, setIsFocusMode] = useState(false);
  const [dynamicData, setDynamicData] = useState<any>(null);
  const [bgUrl, setBgUrl] = useState('https://flowsalon.id/absenku/florida.webp');
  const [materiOfTheDay, setMateriOfTheDay] = useState<any>(null);

  useEffect(() => {
    const saved = localStorage.getItem('flow_user');
    if (saved) {
      const u = JSON.parse(saved);
      setUser(u);
      fetchGlobalData(u.email);
    }
  }, []);

  useEffect(() => {
    if (showMateri) {
      setIsFocusMode(true);
    }
  }, [showMateri]);

  const fetchGlobalData = async (email: string) => {
    const data = await api.getInitialData(email);
    if (data) {
      setDynamicData(data);
      calculateMateriOfTheDay(data.materiList, data.lastLog);
    }
  };

  const calculateMateriOfTheDay = (materiList: any[], lastLog: any) => {
    if (!materiList || materiList.length === 0) return;

    // Jika belum pernah absen, materi pertama
    if (!lastLog) {
      setMateriOfTheDay(materiList[0]);
      return;
    }

    const lastDateObj = parseDateSafe(lastLog.waktu);
    // Jika tanggal tidak valid, materi pertama
    if (!lastDateObj) {
      setMateriOfTheDay(materiList[0]);
      return;
    }

    const todayDateObj = new Date();
    // Bandingkan tanggal untuk menentukan apakah hari ini sudah absen
    const isSameDay = lastDateObj.toDateString() === todayDateObj.toDateString();

    const normalize = (s: string) => (s || "").toString().trim().toLowerCase();
    const lastMateriLog = normalize(lastLog.materi);

    // --- LOGIKA PENCOCOKAN MATERI (NUMERIC MATCHING) ---
    // Ekstrak angka pertama dari string (misal "Bab 1..." -> 1)
    const extractNumber = (str: string) => {
      const match = str.match(/(\d+)/);
      return match ? parseInt(match[1]) : null;
    };

    const lastLogNum = extractNumber(lastMateriLog);

    let lastIndex = materiList.findIndex(m => {
       const b = normalize(m.bab);
       const j = normalize(m.judul);

       // 1. Cek kesamaan persis (String Match)
       if (b === lastMateriLog || j === lastMateriLog) return true;

       // 2. Cek kesamaan Angka (Numeric Match) - Paling Akurat untuk variasi nama
       // Misal Log: "Bab 1: Fisik" (Num: 1) vs Master: "Bab 1" (Num: 1) -> MATCH
       const babNum = extractNumber(m.bab);

       if (lastLogNum !== null && babNum !== null) {
         if (babNum === lastLogNum) return true;
       }

       // 3. Fallback: Contains String
       if (lastMateriLog.includes(b) && b.length > 3) return true;

       return false;
    });

    // Jika masih tidak ketemu (-1), berarti materi di log tidak dikenali atau format beda jauh.
    // Default ke index 0 (Materi Pertama)
    if (lastIndex === -1) lastIndex = 0;

    if (isSameDay) {
      // Jika hari ini user SUDAH absen (Row untuk hari ini sudah ada di sheet),
      // maka tampilkan materi yang SAMA dengan yang tercatat di log hari ini.
      // Ini mencegah materi loncat jika user refresh halaman setelah absen.
      setMateriOfTheDay(materiList[lastIndex]);
    } else {
      // Jika log terakhir adalah KEMARIN (atau lampau), maka user harus dapat materi BERIKUTNYA.
      let nextIndex = lastIndex + 1;

      // Jika sudah sampai materi terakhir, ulang dari awal (Looping)
      if (nextIndex >= materiList.length) {
        nextIndex = 0; 
      }
      setMateriOfTheDay(materiList[nextIndex]);
    }
  };

  const handleLogin = (userData: User) => {
    setUser(userData);
    localStorage.setItem('flow_user', JSON.stringify(userData));
    fetchGlobalData(userData.email);
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('flow_user');
    setCurrentPage(Page.Dashboard);
  };

  const handleAttendanceSuccess = () => {
    if (materiOfTheDay) {
      setShowMateri(true);
    } else {
      setCurrentPage(Page.Dashboard);
    }
  };

  if (!user) return <Login onLogin={handleLogin} />;

  const renderPage = () => {
    switch (currentPage) {
      case Page.Dashboard: return <Dashboard user={user} pesanManager={dynamicData?.pesanManager} onNavigate={setCurrentPage} />;
      case Page.Attendance: 
        return <Attendance 
          user={user} 
          onAttendanceSuccess={handleAttendanceSuccess} 
          lokasiData={dynamicData?.lokasi || []} 
          currentMateri={materiOfTheDay} 
          joinDate={dynamicData?.joinDate || null} // Pass Join Date
        />;
      case Page.Checklist: return <Checklist user={user} tugasMaster={dynamicData?.tugasDef || []} />;
      case Page.Knowledge: return <KnowledgeBase user={user} sopData={dynamicData?.sop || []} onToggleFocus={setIsFocusMode} />;
      case Page.Salary: return <Salary />;
      case Page.Tips: return <Tips tipsData={dynamicData?.tips || []} onToggleFocus={setIsFocusMode} />;
      case Page.Settings: return <Settings currentBg={bgUrl} onUpdateBg={setBgUrl} />;
      default: return <Dashboard user={user} onNavigate={setCurrentPage} />;
    }
  };

  const cleanJudul = (materiOfTheDay?.judul || "Pelajaran Hari Ini").replace(/Modul\s*:\s*/gi, "");

  return (
    <div className="min-h-screen bg-transparent">
      <div 
        className="fixed-bg"
        style={{ backgroundImage: `url(${bgUrl})` }}
      />

      <div className="relative z-10 min-h-screen bg-transparent">
        {!showMateri ? (
          <Layout 
            activePage={currentPage} 
            user={user} 
            onNavigate={setCurrentPage} 
            onLogout={handleLogout}
            isFocusMode={isFocusMode}
          >
            <div className="animate-in fade-in duration-700 bg-transparent w-full">
              {renderPage()}
            </div>
          </Layout>
        ) : (
          <div className="fixed inset-0 z-[2000] bg-black/5 overflow-y-auto px-6 animate-in fade-in duration-300 flex flex-col items-center">
            <div className="w-full max-w-lg space-y-6 py-12">
              <div className="glass-card !rounded-[3.5rem] shadow-2xl overflow-hidden text-left bg-black/20">
                <div className="p-10 border-b border-white/10">
                  <h3 className="text-3xl font-black text-white tracking-normal leading-tight">
                    {toTitleCase(cleanJudul)}
                  </h3>
                  <p className="text-sm text-emerald-glow uppercase font-black mt-3 tracking-[0.2em]">{materiOfTheDay?.sub_judul}</p>
                </div>

                <div className="p-10 space-y-8">
                  <div className="inline-flex items-center gap-3 px-4 py-1.5 rounded-full bg-emerald-400/10 border border-emerald-400/20">
                    <span className="text-emerald-glow text-[10px] font-black uppercase tracking-[0.2em]">
                      {materiOfTheDay?.bab || "EDUKASI"}
                    </span>
                  </div>
                  <div className="text-lg leading-relaxed text-white/90 font-medium whitespace-pre-line">
                    {materiOfTheDay?.isi}
                  </div>
                </div>
              </div>

              <button 
                onClick={() => { 
                  localStorage.setItem('force_attendance_view', 'laporan');
                  setShowMateri(false); 
                  setIsFocusMode(false); 
                  setCurrentPage(Page.Attendance);
                }} 
                className="glass-button h-20 w-full shadow-2xl !bg-white/5 border border-white/10 uppercase tracking-[0.4em] text-[11px] font-black active-emerald-tab"
              >
                Selesai membaca
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

